/* Ma farde de stage — site statique et local-first.
   Les documents ajoutés sont conservés dans IndexedDB sur CET appareil/navigateur.
   Aucun document n'est envoyé à un serveur. */
'use strict';

const $ = (sel, ctx=document) => ctx.querySelector(sel);
const $$ = (sel, ctx=document) => [...ctx.querySelectorAll(sel)];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const newId = () => (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : `file-${Date.now()}-${Math.random().toString(36).slice(2)}`;
// Les pages de garde et de sommaire précèdent les intercalaires : elles ne sont pas numérotées.
// Exactement 9 intercalaires principaux, dans l'ordre choisi pour le stage.
const sections = [
  {id:'guidelines',label:'Consignes',name:'Consignes de stage',color:'#efc4b5',number:'01',description:'Consignes générales 2026–2027 et complément AIP3'},
  {id:'admin',label:'Admin.',name:'Documents administratifs',color:'#dacbe5',number:'02',description:'Convention, feuille de route, documents du maître de stage'},
  {id:'planning',label:'Planning',name:'Planning de stage',color:'#b2d7e4',number:'03',description:'Horaires des trois semaines'},
  {id:'school',label:'École',name:'Présentation de l’école',color:'#e8d7a9',number:'04',description:'Présentation de Clair-Soleil, ROI, projets éducatif et pédagogique'},
  {id:'ep',label:'Infos EP',name:'Informations spécifiques EP',color:'#c8e2a2',number:'05',description:'Plans des gymnases, matériel, classes, compétences, routines'},
  {id:'technical',label:'Fiches',name:'Fiches matières / techniques',color:'#bfdde0',number:'06',description:'Deux fiches demandées et référents didactiques'},
  {id:'days',label:'Journées',name:'Journées de stage',color:'#93d7cd',number:'07',description:'Préparations, observations et auto-évaluations classées par jour'},
  {id:'reflection',label:'Réflexion',name:'Analyse réflexive',color:'#efd6a3',number:'08',description:'Analyse d’une situation d’apprentissage vécue'},
  {id:'conclusion',label:'Bilan',name:'Conclusion personnelle',color:'#d9c4e9',number:'09',description:'Bilan final et compétences à améliorer'}
];
const builtinDocs = [
  {id:'b-general',name:'Consignes générales des stages · 2026–2027',section:'guidelines',type:'application/pdf',url:'documents/consignes-generales-2026-2027.pdf',subtitle:'Document HEFF transmis · 12 pages'},
  {id:'b-complement',name:'Complément de consignes · AIP3 (2025–2026)',section:'guidelines',type:'application/pdf',url:'documents/complement-consignes-AIP3-2025-2026.pdf',subtitle:'Document HEFF transmis · 15 pages · édition antérieure',outdated:true},
  {id:'b-accord',name:'Accord de collaboration pédagogique · 2026–2027',section:'admin',type:'application/pdf',url:'documents/accord-collaboration-pedagogique-2026-2027.pdf',subtitle:'Document à compléter et à faire signer · 2 pages'},
  {id:'b-attestation',name:'Attestation d’encadrement pédagogique',section:'admin',type:'application/pdf',url:'documents/attestation-encadrement-pedagogique.pdf',subtitle:'Demande d’allocation et signatures · 1 page'},
  {id:'b-rapport',name:'Rapport du maître de stage',section:'admin',type:'application/pdf',url:'documents/rapport-maitre-de-stage.pdf',subtitle:'Grille et rapport destinés au maître de stage · 6 pages'},
  {id:'b-planning-a',name:'Horaire de M. Mottry · Semaine A',section:'planning',type:'application/pdf',url:'documents/horaire-mottry-semaine-A.pdf',subtitle:'Horaire original du maître de stage · Semaine A'},
  {id:'b-planning-b',name:'Horaire de M. Mottry · Semaine B',section:'planning',type:'application/pdf',url:'documents/horaire-mottry-semaine-B.pdf',subtitle:'Horaire original du maître de stage · Semaine B'}
];
const checklist = [
  {id:'g-cover',section:'summary',text:'Vérifier la page de garde (école, classe, dates, maître de stage)'},
  {id:'g-general',section:'guidelines',text:'Consulter les consignes générales 2026–2027 et vérifier le complément AIP3'},
  {id:'g-agreement',section:'admin',text:'Faire signer la convention de stage'},
  {id:'g-route',section:'admin',text:'Compléter la feuille de route et la faire signer lors des visites'},
  {id:'g-week1',section:'planning',text:'Compléter et communiquer l’horaire de la première semaine'},
  {id:'g-roi',section:'school',text:'Ajouter le ROI et présenter l’école Clair-Soleil'},
  {id:'g-gym',section:'ep',text:'Faire le plan du gymnase et l’inventaire du matériel'},
  {id:'g-classes',section:'ep',text:'Rassembler les informations sur les classes et leurs compétences'},
  {id:'g-mat',section:'technical',text:'Préparer les deux fiches matières / techniques et les référents didactiques'},
  {id:'g-collect',section:'reflection',text:'Rédiger l’analyse d’une situation d’apprentissage vécue'},
  {id:'g-conclusion',section:'conclusion',text:'Réaliser la conclusion personnelle de stage'}
];
const DEFAULT_SCHOOL_LOGO = 'data:image/png;base64,';
const DEFAULT_META = {name:'Lucas Devers',school:'École Clair-Soleil',mentor:'Monsieur Mottry',className:'Section 3 · Éducation physique',start:'2026-11-02',weeks:3,schoolLogo:DEFAULT_SCHOOL_LOGO};
const STORE_KEY = 'maFardeStage_v3';
const VIEW_KEY = 'maFardeStage_viewMode';
// Code d’ajout côté navigateur : contrôle de l'interface, pas un contrôle d'accès au site.
const DOCUMENT_ADD_CODE = 'farde 2026';
let pendingProtectedUpload = null;

const state = {meta:{...DEFAULT_META},checks:{},notes:{},placements:{},docs:[],open:false,section:'cover',week:0,day:0,db:null,dbError:false,pendingFiles:[],movingId:null,viewerUrl:null,toastTimer:0,viewMode:'tabs',flipBusy:false,flipTimer:null};
function updatedSection(doc){
  if(doc.section === 'info'){
    const title=String(doc.name||'').toLocaleLowerCase('fr-BE');
    if(/matière|technique|fiche|référent|didactique/.test(title))return 'technical';
    if(/gymnase|gym|matériel|effectif|compétence|classe|routine|installation|sécurité/.test(title))return 'ep';
    return 'school';
  }
  if(doc.section === 'appendices')return 'technical';
  return sections.some(s=>s.id===doc.section) ? doc.section : 'admin';
}
function migrateNotes(){
  if(state.notes.info && !state.notes.school)state.notes.school=state.notes.info;
  if(state.notes.appendices && !state.notes.technical)state.notes.technical=state.notes.appendices;
}


function setSaveStatus(message,failed=false){
  const el=$('#saveStatus');if(!el)return;
  el.textContent=message;el.classList.toggle('save-error',failed);
  el.title=failed?'La sauvegarde locale a échoué. Exporte une sauvegarde et vérifie le stockage du navigateur.':'Données enregistrées automatiquement sur cet appareil, dans ce navigateur. Pour les transférer, utilise « Sauvegarder ».';
}
function persist(){
  try{
    localStorage.setItem(STORE_KEY,JSON.stringify({meta:state.meta,checks:state.checks,notes:state.notes,placements:state.placements}));
    setSaveStatus('✓ Enregistré sur cet appareil');
  }catch(err){console.warn('Enregistrement impossible',err);setSaveStatus('⚠ Sauvegarde indisponible',true);}
}
function effectiveBuiltins(){return builtinDocs.map(f=>({...f,...(state.placements[f.id]||{})}));}
function retrieve(){
  try{state.viewMode=localStorage.getItem(VIEW_KEY)==='book'?'book':'tabs';}catch(err){state.viewMode='tabs';}
  try{
    const data = JSON.parse(localStorage.getItem(STORE_KEY)||'null');
    if(data && typeof data === 'object'){
      if(data.meta) state.meta={...DEFAULT_META,...data.meta};
      if(data.checks && typeof data.checks === 'object') state.checks=data.checks;
      if(data.notes && typeof data.notes === 'object') state.notes=data.notes;
      if(data.placements && typeof data.placements==='object') state.placements=data.placements;
      migrateNotes();
    }
  }catch(err){console.warn('Préférences non chargées',err);}
}
function getDays(){
  const d = new Date(`${state.meta.start || DEFAULT_META.start}T12:00:00`);
  if(!Number.isFinite(d.getTime())) d.setTime(new Date(`${DEFAULT_META.start}T12:00:00`).getTime());
  const wanted=Math.max(1,Math.min(4,parseInt(state.meta.weeks,10)||3))*5, dates=[];
  while(dates.length<wanted){if(d.getDay()!==0&&d.getDay()!==6) dates.push(new Date(d));d.setDate(d.getDate()+1);}
  return dates;
}
function formatDate(d,opts={weekday:'long',day:'numeric',month:'long'}){return new Intl.DateTimeFormat('fr-BE',opts).format(d);}
function dayLabel(i){const date=getDays()[i]; return date?`${formatDate(date)} · Jour ${i+1}`:`Jour ${i+1}`;}
function currentSection(){if(state.section==='cover')return {id:'cover',name:'Page de garde'};if(state.section==='summary')return {id:'summary',name:'Sommaire'};return sections.find(s=>s.id===state.section)||{id:'cover',name:'Page de garde'};}
function countDocs(sec,day=null){return [...effectiveBuiltins(),...state.docs].filter(f=>f.section===sec && (sec!=='days'||day===null||f.day===day||f.day===null||f.day===undefined)).length;}
function fileSize(n){if(!n)return '';if(n<1024)return `${n} o`;if(n<1048576)return `${(n/1024).toFixed(0)} Ko`;return `${(n/1048576).toFixed(1)} Mo`;}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function iconSymbol(type){if(type?.includes('pdf')||String(type).endsWith('.pdf'))return ['PDF','pdf'];if(type?.includes('word')||String(type).match(/docx?/))return ['DOC','word'];if(type?.startsWith('image/'))return ['IMG','image'];return ['DOC',''];}

function pageHead(title,subtitle,number){
  return `<div class="page-head"><div><div class="page-label">FARDE DE STAGE · AIP 3 / ${esc(String(state.meta.start).slice(0,4))}—${esc(String(Number(String(state.meta.start).slice(0,4))+1))}</div><h2 class="page-title">${esc(title)}</h2><p class="page-description">${esc(subtitle)}</p></div><div class="page-index">${number}</div></div>`;
}
function tiny(t){return `<div class="tiny-heading">${esc(t)}</div>`;}
function noteBox(key,placeholder='Écris ici tes notes, remarques ou informations utiles…'){
  return `<textarea class="note-area" data-note="${esc(key)}" placeholder="${esc(placeholder)}">${esc(state.notes[key]||'')}</textarea><div class="notes-footer"><span>✎ Notes personnelles</span><span>Enregistrement automatique sur cet appareil</span></div>`;
}
function checkLine(c){return `<label class="checkline ${state.checks[c.id]?'checked':''}"><input type="checkbox" data-check="${esc(c.id)}" ${state.checks[c.id]?'checked':''}/><span>${esc(c.text)}</span></label>`;}
function checkList(arr){return `<div class="checklist">${arr.map(checkLine).join('')}</div>`;}
function docRow(f){
  const [code,klass]=iconSymbol(f.type||f.name);
  const builtin=Boolean(f.url);
  let meta=builtin?f.subtitle:`Ajouté le ${new Date(f.uploadedAt||Date.now()).toLocaleDateString('fr-BE')} · ${fileSize(f.size)}`;
  if(f.outdated)meta+=' · À vérifier';
  return `<div class="doc-row" data-doc="${esc(f.id)}"><div class="doc-icon ${klass}">${code}</div><div class="doc-info"><span class="doc-title" title="${esc(f.name)}">${esc(f.name)}</span><div class="doc-meta">${esc(meta)}</div></div><div class="doc-actions"><button class="small-action" type="button" data-view="${esc(f.id)}">Ouvrir ↗</button><button class="small-action" type="button" data-move="${esc(f.id)}" title="Déplacer ce document vers un autre intercalaire ou jour">↔ Déplacer</button>${builtin?'':`<button class="small-action danger" type="button" data-delete="${esc(f.id)}" title="Supprimer">×</button>`}</div></div>`;
}
function fileList(section,day=null){
  const docs=[...effectiveBuiltins(),...state.docs].filter(f=>f.section===section && (section!=='days'||f.day===day||f.day===null||f.day===undefined));
  const uploadAttrs=`data-upload-to="${esc(section)}" ${section==='days'?`data-day-to="${day}"`:''}`;
  if(!docs.length){
    return `<div class="empty-state empty-documents"><div class="empty-ico">＋</div><strong>Aucun document pour le moment</strong><p>Cet intercalaire est vide. Ajoute tes fichiers quand tu en auras besoin.</p><button class="button button-primary empty-upload" type="button" ${uploadAttrs}>＋ Ajouter mon premier document</button><small>PDF, Word, images... tu peux en ajouter plusieurs à la fois.</small></div>`;
  }
  return `<div class="doc-list">${docs.map(docRow).join('')}</div><button class="add-inline" type="button" ${uploadAttrs}>＋ Ajouter un autre document</button>`;
}
function callout(text,warn=false){return `<div class="info-callout ${warn?'warn':''}">${text}</div>`;}

function coverPage(){
  const last=getDays().at(-1), school=state.meta.school||'Établissement à compléter',mentor=state.meta.mentor||'À compléter';
  const logo = state.meta.schoolLogo || DEFAULT_SCHOOL_LOGO;
  return `<div class="cover-page"><div class="heff-label">HAUTE ÉCOLE FRANCISCO FERRER<br>SECTION 3 · ÉDUCATION PHYSIQUE</div>${logo?`<div class="school-logo-wrap"><img src="${logo}" alt="Logo de l’école ${esc(school)}" class="school-logo"></div>`:''}<div class="cover-page-icon">✳</div><div><div class="page-label">ACTIVITÉS D’INTÉGRATION PROFESSIONNELLE · AIP3</div><h2>FARDE<br>DE <em>STAGE</em></h2><h3>${esc(state.meta.name)}</h3><div class="fine">${esc(state.meta.className)}<br>${esc(state.meta.school||'École de stage à renseigner')}<br>Maître de stage : ${esc(mentor)}</div></div><footer>DU ${esc(formatDate(getDays()[0],{day:'numeric',month:'long',year:'numeric'}).toUpperCase())} AU ${esc(formatDate(last,{day:'numeric',month:'long',year:'numeric'}).toUpperCase())}<br><button class="small-action no-print" style="margin-top:9px" type="button" data-settings>✎ Modifier les informations</button> <button class="small-action no-print" type="button" data-print>⎙ Imprimer la page</button></footer></div>`;
}
function summaryPage(){
  return pageHead('Sommaire','La page de garde, ce sommaire, puis tes 9 intercalaires à remplir au fur et à mesure.','—')+
    `<div class="grid-2"><div class="dashboard-stat"><strong>9</strong><span>INTERCALAIRES PRINCIPAUX</span></div><div class="dashboard-stat"><strong>${getDays().length}</strong><span>JOURNÉES DE STAGE</span></div></div>`+
    tiny('Les 9 intercalaires')+`<div class="grid-2">${sections.map(s=>`<button class="section-shortcut" type="button" data-nav="${s.id}"><span class="shortcut-number">${s.number}</span><span class="shortcut-main">${esc(s.name)}<small class="shortcut-desc">${esc(s.description)}</small></span><span class="shortcut-arrow">›</span></button>`).join('')}</div>`+
    
    callout('Les <strong>2 consignes</strong> sont dans l’intercalaire <strong>01</strong>, et tes <strong>3 documents administratifs</strong> sont dans l’intercalaire <strong>02</strong> et les <strong>2 horaires A/B</strong> dans l’intercalaire <strong>03</strong>. Les autres intercalaires sont vides et prêts à être remplis.');
}
function simpleEmptyPage(sectionId){
  const sec=sections.find(s=>s.id===sectionId);
  return pageHead(sec.name,sec.description,sec.number)+fileList(sectionId);
}
function guidelinesPage(){
  return pageHead('Consignes de stage','Tes deux documents transmis sont déjà rangés ici.','01')+
    callout('<strong>Attention :</strong> le complément AIP3 fourni est daté de 2025–2026, contrairement aux consignes générales 2026–2027. Vérifie auprès de la HEFF si une version plus récente existe.',true)+
    tiny('Mes consignes générales et AIP3')+fileList('guidelines');
}
function adminPage(){return simpleEmptyPage('admin');}
function planningPage(){return pageHead('Planning de stage','Les deux horaires officiels de M. Mottry : Semaine A et Semaine B.','03')+callout('Les horaires A et B proviennent du maître de stage. Leur affectation exacte aux dates du <strong>2 au 20 novembre 2026</strong> reste à confirmer ; aucun planning hebdomadaire n’a été inventé.')+fileList('planning');}
function schoolPage(){return simpleEmptyPage('school');}
function epPage(){return simpleEmptyPage('ep');}
function technicalPage(){return simpleEmptyPage('technical');}
function dayPage(requestedDay = state.day){
  const dates=getDays();
  const id=Math.max(0,Math.min(dates.length-1,requestedDay));
  const week=Math.floor(id/5);
  const tabs=dates.slice(week*5,week*5+5).map((d,index)=>{const idx=week*5+index;return `<button class="day-tab ${idx===id?'active':''}" type="button" data-day="${idx}" aria-pressed="${idx===id}"><strong>JOUR ${String(idx+1).padStart(2,'0')}</strong><span>${esc(formatDate(d,{day:'numeric',month:'short'}))}</span></button>`;}).join('');
  const d=dates[id];
  return pageHead('Journées de stage','Choisis une journée, puis ajoute tes préparations, observations et auto-évaluations.','07')+
    `<div class="week-selector">${Array.from({length:Math.ceil(dates.length/5)},(_,w)=>`<button type="button" data-week="${w}" class="${w===week?'active':''}">Semaine ${w+1}</button>`).join('')}</div>`+
    `<div class="day-tabs" aria-label="Journées du stage">${tabs}</div><div class="day-date">${esc(formatDate(d))} · Jour ${id+1} sur ${dates.length}</div>`+
    fileList('days',id);
}
function reflectionPage(){return simpleEmptyPage('reflection');}
function conclusionPage(){return simpleEmptyPage('conclusion');}
const pageRenderers={cover:coverPage,summary:summaryPage,guidelines:guidelinesPage,admin:adminPage,planning:planningPage,school:schoolPage,ep:epPage,technical:technicalPage,days:dayPage,reflection:reflectionPage,conclusion:conclusionPage};
/* Livre à pages : la vue par intercalaires reste entièrement disponible.
   La double-page montre la page précédente à gauche et la page actuelle à droite.
   Les journées sont de vraies pages successives du livre. */
function bookSequence(){
  const base=[{id:'cover',title:'Page de garde'},{id:'summary',title:'Sommaire'}];
  for(const sec of sections){
    if(sec.id==='days'){
      for(let i=0;i<getDays().length;i++)base.push({id:'days',day:i,title:`Jour ${String(i+1).padStart(2,'0')} · ${formatDate(getDays()[i],{day:'numeric',month:'short'})}`});
    }else base.push({id:sec.id,title:`${sec.number} · ${sec.name}`});
  }
  return base;
}
function bookPosition(pages=bookSequence()){
  const found=pages.findIndex(page=>page.id===state.section && (page.id!=='days'||page.day===state.day));
  return found<0?0:found;
}
function pageHTML(page){
  if(!page)return '<div class="book-endpaper"><span>✳</span><strong>MA FARDE<br>DE STAGE</strong><small>ÉCOLE CLAIR-SOLEIL · AIP 3</small></div>';
  return page.id==='days'?dayPage(page.day):pageRenderers[page.id]();
}
function renderBook(){
  const pages=bookSequence(),index=bookPosition(pages);
  $('#bookLeftContent').innerHTML=pageHTML(index>0?pages[index-1]:null);
  $('#bookRightContent').innerHTML=pageHTML(pages[index]);
  $('#bookLeftContent').scrollTop=0;
  $('#bookRightContent').scrollTop=0;
  $('#bookPageCounter').textContent=`Page ${index+1} sur ${pages.length}`;
  $('#bookChapter').textContent=pages[index].title;
  $('#bookPrev').disabled=index===0;
  $('#bookNext').disabled=index===pages.length-1;
  $('#bookQuickTabs').innerHTML=sections.map(s=>`<button type="button" data-nav="${s.id}" class="book-chapter ${s.id===state.section?'selected':''}" style="--tab-color:${s.color}" title="${esc(s.name)}"><span>${s.number}</span>${esc(s.label)}</button>`).join('');
}
function setViewMode(mode){
  if(mode!=='tabs'&&mode!=='book')return;
  if(state.flipBusy)return;
  state.viewMode=mode;
  try{localStorage.setItem(VIEW_KEY,mode);}catch(err){}
  render();
}
function goBook(delta){
  if(!state.open||state.viewMode!=='book'||state.flipBusy)return;
  const pages=bookSequence(),old=bookPosition(pages),next=old+delta;
  if(next<0||next>=pages.length)return;
  const flip=$('#bookFlip');
  state.flipBusy=true;
  const forward=delta>0;
  const frontHtml=forward?$('#bookRightContent').innerHTML:$('#bookLeftContent').innerHTML;
  const backHtml=forward?pageHTML(pages[next]):pageHTML(pages[next]);
  flip.className=`book-flip ${forward?'flip-forward':'flip-backward'}`;
  flip.innerHTML=`<div class="flip-face flip-front"><div class="flip-face-content">${frontHtml}</div></div><div class="flip-face flip-back"><div class="flip-face-content">${backHtml}</div></div>`;
  flip.hidden=false;
  // Two requestAnimationFrames allow the browser to paint the paper before turning.
  requestAnimationFrame(()=>requestAnimationFrame(()=>flip.classList.add('turning')));
  const complete=()=>{
    clearTimeout(state.flipTimer);
    const pg=pages[next];state.section=pg.id;
    if(pg.id==='days'){state.day=pg.day;state.week=Math.floor(pg.day/5);}
    flip.hidden=true;flip.className='book-flip';flip.replaceChildren();
    state.flipBusy=false;render();
  };
  state.flipTimer=setTimeout(complete,610);
}
function updateProgress(){
  const done=checklist.filter(x=>state.checks[x.id]).length;
  $('#progressText').textContent=`${done} / ${checklist.length}`;
  $('#progressBar').style.width=`${Math.round((done/checklist.length)*100)}%`;
}
function updateMetaUI(){
  const dates=getDays(), last=dates.at(-1), first=dates[0];
  $('#coverName').textContent=state.meta.name.toUpperCase();
  $('#stageSubtitle').textContent=`${state.meta.name} · ${state.meta.school||'École à renseigner'} · ${formatDate(first,{day:'numeric',month:'short'})} – ${formatDate(last,{day:'numeric',month:'short',year:'numeric'})}`;
  $('#insideInfo').innerHTML=`<span>MAÎTRE DE STAGE</span>${esc(state.meta.mentor||'À renseigner')}<br><span style="margin-top:14px">ÉTABLISSEMENT</span>${esc(state.meta.school||'À renseigner')}`;
}
function render(){
  $('#welcome').hidden=state.open;$('#opened').hidden=!state.open;
  updateMetaUI();
  if(!state.open)return;
  const section=currentSection();
  $('#pageHead').textContent=state.section==='summary'?'Sommaire':state.section==='cover'?'Page de garde':section.name;
  $('#binderScene').hidden=state.viewMode!=='tabs';
  $('#bookScene').hidden=state.viewMode!=='book';
  $('#viewTabs').classList.toggle('active',state.viewMode==='tabs');
  $('#viewTabs').setAttribute('aria-pressed',String(state.viewMode==='tabs'));
  $('#viewBook').classList.toggle('active',state.viewMode==='book');
  $('#viewBook').setAttribute('aria-pressed',String(state.viewMode==='book'));
  $('#paperInner').innerHTML=pageRenderers[section.id]();
  $('#sideTabs').innerHTML=sections.map(s=>`<button class="side-tab ${s.id===state.section?'active':''}" style="background:${s.color}" data-nav="${s.id}" type="button" title="${esc(s.name)}" aria-label="${esc(s.name)}" aria-current="${s.id===state.section?'page':'false'}"><span class="number">${s.number}</span>${esc(s.label)}</button>`).join('');
  $('#paperInner').scrollTop=0;
  if(state.viewMode==='book')renderBook();
  updateProgress();
}
function navigate(sec){if(!pageRenderers[sec])return;state.section=sec;render();}
function openFarde(){state.open=true;state.section='cover';render();window.scrollTo({top:0,behavior:'smooth'});}
function closeFarde(){state.open=false;render();window.scrollTo({top:0,behavior:'smooth'});}

/* IndexedDB file storage: file Blobs stay locally available after reloading. */
async function startDb(){
  if(!('indexedDB' in window)){state.dbError=true;setSaveStatus('⚠ Stockage indisponible',true);toast('Stockage automatique indisponible dans ce navigateur.');return;}
  try{
    state.db=await new Promise((resolve,reject)=>{
      const req=indexedDB.open('MaFardeStageFiles',1);
      req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('files'))req.result.createObjectStore('files',{keyPath:'id'});};
      req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);
    });
    state.docs=await new Promise((resolve,reject)=>{
      const tx=state.db.transaction('files','readonly');const req=tx.objectStore('files').getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);
    });
    setSaveStatus('✓ Sauvegarde automatique active');
    // Migrer les éventuels documents enregistrés avec l'ancien classement.
    for(const f of state.docs){const updated=updatedSection(f);if(updated!==f.section){f.section=updated;await dbSave(f);}}

  }catch(err){console.warn(err);state.dbError=true;setSaveStatus('⚠ Stockage indisponible',true);toast('Stockage automatique indisponible dans ce navigateur.');}
}
function dbSave(f){return new Promise((resolve,reject)=>{if(!state.db)return reject(new Error('Stockage local indisponible'));const tx=state.db.transaction('files','readwrite');tx.objectStore('files').put(f);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
function dbRemove(id){return new Promise((resolve,reject)=>{if(!state.db)return reject(new Error('Stockage local indisponible'));const tx=state.db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
function dbClear(){return new Promise((resolve,reject)=>{if(!state.db)return reject(new Error('Stockage local indisponible'));const tx=state.db.transaction('files','readwrite');tx.objectStore('files').clear();tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
function getDoc(id){return effectiveBuiltins().find(f=>f.id===id)||state.docs.find(f=>f.id===id);}

function fillSelectors(sectionSelect,daySelect){
  const sec=$(sectionSelect), day=$(daySelect);if(!sec||!day)return;
  sec.innerHTML=sections.filter(x=>!['cover','summary'].includes(x.id)).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');
  day.innerHTML=getDays().map((d,i)=>`<option value="${i}">Jour ${i+1} — ${esc(formatDate(d,{day:'numeric',month:'short'}))}</option>`).join('');
}
function daySelectorVisibility(sectionSelector,wrapSelector){const day=$(sectionSelector).value==='days';$(wrapSelector).hidden=!day;}
function requestUpload(to=state.section,day=state.day,files=null){
  // Une validation est demandée à chaque opération, même par glisser-déposer.
  pendingProtectedUpload={kind:'upload',to,day,files:files?Array.from(files):null};
  $('#addCode').value='';
  $('#addCode').type='password';
  $('#toggleCode').textContent='Afficher';
  $('#codeFeedback').textContent='';
  $('#codeDialog').showModal();
  $('#addCode').focus();
}
function requestRestore(){
  pendingProtectedUpload={kind:'restore'};
  $('#addCode').value='';
  $('#addCode').type='password';
  $('#toggleCode').textContent='Afficher';
  $('#codeFeedback').textContent='';
  $('#codeDialog').showModal();
  $('#addCode').focus();
}
function verifyAddCode(event){
  event.preventDefault();
  if(!pendingProtectedUpload)return;
  if($('#addCode').value!==DOCUMENT_ADD_CODE){
    $('#codeFeedback').textContent='Code incorrect. Vérifie les espaces et réessaie.';
    $('#addCode').value='';
    $('#addCode').focus();
    return;
  }
  const approved=pendingProtectedUpload;
  pendingProtectedUpload=null;
  $('#addCode').value='';
  $('#codeDialog').close();
  if(approved.kind==='restore'){
    $('#restoreFile').click();
    return;
  }
  showUpload(approved.to,approved.day);
  if(approved.files?.length)updatePending(approved.files);
}
function showUpload(to=state.section,day=state.day){
  if(!state.open){openFarde();}
  state.pendingFiles=[];$('#uploadFiles').value='';$('#fileSelection').textContent='Aucun fichier sélectionné';
  fillSelectors('#uploadSection','#uploadDay');
  $('#uploadSection').value=['cover','summary'].includes(to)?'admin':to;
  $('#uploadDay').value=String(day);
  daySelectorVisibility('#uploadSection','#uploadDayWrap');
  $('#uploadDialog').showModal();
}
function updatePending(files){state.pendingFiles=Array.from(files||[]);$('#fileSelection').textContent=state.pendingFiles.length?state.pendingFiles.map(f=>`${f.name} (${fileSize(f.size)})`).join(' · '):'Aucun fichier sélectionné';}
async function uploadDocuments(ev){
  ev.preventDefault();
  // Autorisation de conservation longue durée, uniquement si le navigateur la propose.
  try{await navigator.storage?.persist?.();}catch(err){}
  const files=state.pendingFiles,sec=$('#uploadSection').value,day=sec==='days'?parseInt($('#uploadDay').value,10):null;
  if(!files.length){toast('Choisis au moins un document.');return;}
  if(files.some(f=>f.size>25*1024*1024)){toast('Un fichier dépasse 25 Mo.');return;}
  const submit=$('#uploadForm button[type=submit]');submit.disabled=true;submit.textContent='Enregistrement…';
  try{
    for(const file of files){const obj={id:newId(),name:file.name,type:file.type||'application/octet-stream',size:file.size,uploadedAt:Date.now(),section:sec,day,blob:file};await dbSave(obj);state.docs.push(obj);}
    setSaveStatus('✓ Documents sauvegardés');
    $('#uploadDialog').close();state.section=sec;if(day!==null){state.day=day;state.week=Math.floor(day/5);}render();toast(state.dbError?'Fichier ajouté temporairement : télécharge une sauvegarde pour le conserver.':`${files.length} document${files.length>1?'s':''} rangé${files.length>1?'s':''} dans ta farde.`);
  }catch(err){console.error(err);toast('Le document n’a pas pu être enregistré. Espace disponible ?');}
  finally{submit.disabled=false;submit.textContent='Ranger dans ma farde ↗';}
}
async function deleteDocument(id){
  const doc=getDoc(id);if(!doc||doc.url)return;
  if(!confirm(`Supprimer « ${doc.name} » de ta farde ?`))return;
  try{await dbRemove(id);state.docs=state.docs.filter(f=>f.id!==id);render();toast('Document supprimé.');}catch(err){toast('Suppression impossible.');}
}
function moveDocument(id){
  const doc=getDoc(id);if(!doc)return;state.movingId=id;
  $('#moveFileName').textContent=doc.name;fillSelectors('#moveSection','#moveDay');
  $('#moveSection').value=doc.section;$('#moveDay').value=doc.day===null?'0':String(doc.day);
  daySelectorVisibility('#moveSection','#moveDayWrap');$('#moveDialog').showModal();
}
async function saveMove(ev){
  ev.preventDefault();const d=getDoc(state.movingId);if(!d)return;
  const sec=$('#moveSection').value,day=sec==='days'?Number($('#moveDay').value):null;
  try{
    if(d.url){ // Les originaux restent inchangés : seul leur classement personnel est mémorisé.
      state.placements[d.id]={section:sec,day};
      persist();
    }else{
      const next={...d,section:sec,day};
      await dbSave(next);
      const idx=state.docs.findIndex(f=>f.id===d.id);
      if(idx>=0)state.docs[idx]=next;
      setSaveStatus('✓ Classement sauvegardé');
    }
    $('#moveDialog').close();state.section=sec;
    if(sec==='days'){state.day=day;state.week=Math.floor(day/5);}
    render();toast('Document déplacé et classement sauvegardé.');
  }catch(err){console.error(err);setSaveStatus('⚠ Déplacement non enregistré',true);toast('Déplacement impossible : stockage indisponible.');}
}
function closeViewer(){const dlg=$('#viewerDialog');if(dlg.open)dlg.close();$('#viewerBody').replaceChildren();if(state.viewerUrl){URL.revokeObjectURL(state.viewerUrl);state.viewerUrl=null;}}
function viewDocument(id){
  const f=getDoc(id);if(!f)return;
  let url=f.url||(f.blob?URL.createObjectURL(f.blob):'');
  // The optional single-file edition embeds the official PDFs as base64.
  if(f.url && window.EMBEDDED_PDFS?.[f.url]){
    const raw=atob(window.EMBEDDED_PDFS[f.url]);const bytes=new Uint8Array(raw.length);
    for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
    url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));
    state.viewerUrl=url;
  }else if(!f.url)state.viewerUrl=url;
  if(!url){toast('Le fichier est introuvable.');return;}
  $('#viewerTitle').textContent=f.name;
  const dl=$('#viewerDownload');dl.href=url;dl.download=f.name + ((f.type||'').includes('pdf') && !f.name.toLowerCase().endsWith('.pdf') ? '.pdf' : '');
  const body=$('#viewerBody');body.replaceChildren();
  const type=(f.type||'').toLowerCase(),pdf=type.includes('pdf')||f.name.toLowerCase().endsWith('.pdf');
  if(pdf){const frame=document.createElement('iframe');frame.src=url;frame.title=`Aperçu : ${f.name}`;body.append(frame);}
  else if(type.startsWith('image/')){const img=document.createElement('img');img.src=url;img.alt=f.name;body.append(img);}
  else{const div=document.createElement('div');div.className='viewer-fallback';div.innerHTML='<h3>Document prêt à télécharger</h3><p>Le navigateur ne peut pas afficher directement ce format (par exemple Word). Utilise « Télécharger » pour l’ouvrir dans son application.</p>';body.append(div);}
  $('#viewerDialog').showModal();
}
function openSettings(){
  $('#metaName').value=state.meta.name;$('#metaSchool').value=state.meta.school;$('#metaMentor').value=state.meta.mentor;$('#metaClass').value=state.meta.className;
  $('#metaDate').value=state.meta.start;$('#metaDuration').value=state.meta.weeks;
  $('#settingsDialog').showModal();
}
function saveSettings(ev){
  ev.preventDefault();state.meta={name:$('#metaName').value.trim()||DEFAULT_META.name,school:$('#metaSchool').value.trim(),mentor:$('#metaMentor').value.trim(),className:$('#metaClass').value.trim(),start:$('#metaDate').value||DEFAULT_META.start,weeks:Number($('#metaDuration').value)||3};
  state.day=0;state.week=0;persist();$('#settingsDialog').close();render();toast('Informations du stage mises à jour.');
}
function searchDocs(q){
  const query=q.trim().toLocaleLowerCase('fr-BE');
  const docs=[...effectiveBuiltins(),...state.docs].filter(f=>`${f.name} ${f.subtitle||''} ${sections.find(s=>s.id===f.section)?.name||''}`.toLocaleLowerCase('fr-BE').includes(query));
  const sec=sections.filter(s=>s.name.toLocaleLowerCase('fr-BE').includes(query));
  const rows=[...docs.map(f=>`<button class="search-row" type="button" data-search-doc="${esc(f.id)}"><span>▤ ${esc(f.name)}</span><small>${esc(sections.find(s=>s.id===f.section)?.name)}</small> ↗</button>`),...sec.map(s=>`<button class="search-row" type="button" data-search-nav="${s.id}"><span>↗ Intercalaire ${esc(s.name)}</span></button>`)];
  $('#searchResults').innerHTML=rows.join('')||'<p class="text-small">Aucun document trouvé.</p>';
}
function blobToDataURL(blob){return new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(reader.result);reader.onerror=()=>rej(reader.error);reader.readAsDataURL(blob);});}
function dataURLtoBlob(data){const [header,b64]=data.split(',');const type=header.match(/data:([^;]+)/)?.[1]||'application/octet-stream';const bytes=atob(b64);const uint=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)uint[i]=bytes.charCodeAt(i);return new Blob([uint],{type});}
function downloadUrl(href,name){const anchor=document.createElement('a');anchor.href=href;anchor.download=name;document.body.append(anchor);anchor.click();anchor.remove();}
async function backupFarde(){
  const b=$('#backupBtn');const old=b.textContent;b.disabled=true;b.textContent='Préparation…';
  try{
    const docs=[];for(const f of state.docs){const {blob,...meta}=f;docs.push({...meta,data:await blobToDataURL(blob)});}
    const payload={application:'Ma Farde de Stage',version:3,createdAt:new Date().toISOString(),meta:state.meta,checks:state.checks,notes:state.notes,placements:state.placements,docs};
    const blob=new Blob([JSON.stringify(payload)],{type:'application/json'});const url=URL.createObjectURL(blob);downloadUrl(url,`ma-farde-stage-${new Date().toISOString().slice(0,10)}.json`);setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Sauvegarde téléchargée. Garde ce fichier en lieu sûr.');
  }catch(err){console.error(err);toast('Erreur pendant la sauvegarde.');}
  finally{b.disabled=false;b.textContent=old;}
}
async function restoreFarde(file){
  if(!file)return;
  if(!confirm('Restaurer cette sauvegarde ? Les documents et notes ajoutés ici seront remplacés.'))return;
  try{
    const backup=JSON.parse(await file.text());if(backup.application!=='Ma Farde de Stage'||!Array.isArray(backup.docs))throw new Error('Fichier incompatible');
    const docs=[];
    for(const f of backup.docs){if(!f.id||!f.name||!f.data)continue;const {data,...meta}=f;meta.section=updatedSection(meta);docs.push({...meta,blob:dataURLtoBlob(data)});}
    await dbClear();for(const d of docs)await dbSave(d);
    state.docs=docs;state.meta={...DEFAULT_META,...(backup.meta||{})};state.notes=backup.notes||{};state.placements=backup.placements||{};migrateNotes();state.checks=backup.checks||{};persist();render();toast('Sauvegarde restaurée avec succès.');
  }catch(err){console.error(err);toast('Cette sauvegarde est invalide ou le stockage est insuffisant.');}
  finally{$('#restoreFile').value='';}
}

function registerEvents(){
  $('#openFromWelcome').addEventListener('click',openFarde);$('#coverButton').addEventListener('click',openFarde);
  $('#brandLink').addEventListener('click',e=>{e.preventDefault();closeFarde();});
  $('#closeBinder').addEventListener('click',closeFarde);
  $('#addBtn').addEventListener('click',()=>requestUpload());
  $('#settingsBtn').addEventListener('click',openSettings);
  $('#searchBtn').addEventListener('click',()=>{$('#searchInput').value='';searchDocs('');$('#searchDialog').showModal();$('#searchInput').focus();});
  $('#backupBtn').addEventListener('click',backupFarde);
  $('#viewTabs').addEventListener('click',()=>setViewMode('tabs'));
  $('#viewBook').addEventListener('click',()=>setViewMode('book'));
  $('#bookPrev').addEventListener('click',()=>goBook(-1));
  $('#bookNext').addEventListener('click',()=>goBook(1));
  $('#restoreBtn').addEventListener('click',requestRestore);
  $('#restoreFile').addEventListener('change',e=>restoreFarde(e.target.files?.[0]));
  $('#uploadSection').addEventListener('change',()=>daySelectorVisibility('#uploadSection','#uploadDayWrap'));
  $('#moveSection').addEventListener('change',()=>daySelectorVisibility('#moveSection','#moveDayWrap'));
  $('#uploadFiles').addEventListener('change',e=>updatePending(e.target.files));
  $('#codeForm').addEventListener('submit',verifyAddCode);
  $('#toggleCode').addEventListener('click',()=>{const field=$('#addCode');const show=field.type==='password';field.type=show?'text':'password';$('#toggleCode').textContent=show?'Masquer':'Afficher';field.focus();});
  $('#codeDialog').addEventListener('close',()=>{pendingProtectedUpload=null;$('#addCode').value='';$('#codeFeedback').textContent='';});
  $('#uploadForm').addEventListener('submit',uploadDocuments);
  $('#settingsForm').addEventListener('submit',saveSettings);
  $('#moveForm').addEventListener('submit',saveMove);
  $('#searchInput').addEventListener('input',e=>searchDocs(e.target.value));
  document.addEventListener('click',e=>{
    if(e.target.closest('[data-book-turn]')){goBook(Number(e.target.closest('[data-book-turn]').dataset.bookTurn));return;}
    const close=e.target.closest('[data-close]');if(close){const dlg=document.getElementById(close.dataset.close);if(dlg?.id==='viewerDialog')closeViewer();else dlg?.close();return;}
    const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}
    const week=e.target.closest('[data-week]');if(week){state.week=Number(week.dataset.week);state.day=state.week*5;render();return;}
    const day=e.target.closest('[data-day]');if(day){state.day=Number(day.dataset.day);state.week=Math.floor(state.day/5);render();return;}
    const upload=e.target.closest('[data-upload-to]');if(upload){requestUpload(upload.dataset.uploadTo,upload.dataset.dayTo?Number(upload.dataset.dayTo):state.day);return;}
    const view=e.target.closest('[data-view]');if(view){viewDocument(view.dataset.view);return;}
    const del=e.target.closest('[data-delete]');if(del){deleteDocument(del.dataset.delete);return;}
    const move=e.target.closest('[data-move]');if(move){moveDocument(move.dataset.move);return;}
    const searchDoc=e.target.closest('[data-search-doc]');if(searchDoc){const f=getDoc(searchDoc.dataset.searchDoc);$('#searchDialog').close();if(f){state.open=true;state.section=f.section;if(f.day!==null&&f.day!==undefined){state.day=f.day;state.week=Math.floor(f.day/5);}render();viewDocument(f.id);}return;}
    const searchNav=e.target.closest('[data-search-nav]');if(searchNav){$('#searchDialog').close();navigate(searchNav.dataset.searchNav);return;}
    if(e.target.closest('[data-settings]')){openSettings();return;}
    if(e.target.closest('[data-print]')){window.print();return;}
  });
  document.addEventListener('change',e=>{
    if(e.target.matches('[data-check]')){
      state.checks[e.target.dataset.check]=e.target.checked;persist();
      e.target.closest('.checkline')?.classList.toggle('checked',e.target.checked);updateProgress();
    }
  });
  document.addEventListener('input',e=>{
    if(e.target.matches('[data-note]')){state.notes[e.target.dataset.note]=e.target.value;persist();}
  });
  $('#searchDialog').addEventListener('click',e=>{if(e.target===$('#searchDialog'))$('#searchDialog').close();});
  ['codeDialog','uploadDialog','settingsDialog','moveDialog'].forEach(id=>{$('#'+id).addEventListener('click',e=>{if(e.target===$('#'+id))$('#'+id).close();});});
  $('#viewerDialog').addEventListener('click',e=>{if(e.target===$('#viewerDialog'))closeViewer();});
  $('#viewerDialog').addEventListener('close',()=>{if(state.viewerUrl){URL.revokeObjectURL(state.viewerUrl);state.viewerUrl=null;}$('#viewerBody').replaceChildren();});
  const dz=$('#dropZone');
  dz.addEventListener('dragover',e=>{e.preventDefault();dz.classList.add('dragging');});
  dz.addEventListener('dragleave',()=>dz.classList.remove('dragging'));
  dz.addEventListener('drop',e=>{e.preventDefault();dz.classList.remove('dragging');updatePending(e.dataTransfer.files);});
  // Déposer un fichier directement sur une feuille ouvre le classement au bon intercalaire.
  $('#paper').addEventListener('dragover',e=>e.preventDefault());
  $('#paper').addEventListener('drop',e=>{e.preventDefault();if(!e.dataTransfer.files.length)return;requestUpload(state.section,state.day,e.dataTransfer.files);});
  document.addEventListener('keydown',e=>{
    if(e.key==='k'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('#searchBtn').click();return;}
    if(state.viewMode!=='book'||!state.open||state.flipBusy||document.querySelector('dialog[open]'))return;
    if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable)return;
    if(e.key==='ArrowRight'){e.preventDefault();goBook(1);}
    else if(e.key==='ArrowLeft'){e.preventDefault();goBook(-1);}
  });
  let touchX=null;
  $('#bookScene').addEventListener('touchstart',e=>{touchX=e.touches[0]?.clientX??null;},{passive:true});
  $('#bookScene').addEventListener('touchend',e=>{if(touchX===null||state.flipBusy)return;const diff=(e.changedTouches[0]?.clientX??touchX)-touchX;touchX=null;if(Math.abs(diff)>75)goBook(diff<0?1:-1);},{passive:true});
}
async function init(){
  retrieve();registerEvents();await startDb();render();
  if(!state.dbError){
    try{if(navigator.storage?.persisted && await navigator.storage.persisted())setSaveStatus('✓ Stockage persistant actif');}
    catch(err){console.debug('Stockage persistant non confirmé',err);}
  }
}
init();
